import{_t as e,it as t,n,rt as r}from"./chunks/framework.XJu5filh.js";import"./chunks/assets.DWopfgZq.js";var i=JSON.parse(`{"title":"神器甄选","description":"","frontmatter":{},"headers":[],"relativePath":"feature/artifact.md","filePath":"feature/artifact.md","lastUpdated":1792333409000}`),a={name:`feature/artifact.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="神器甄选" tabindex="-1">神器甄选 <a class="header-anchor" href="#神器甄选" aria-label="Permalink to “神器甄选”">​</a></h1><p><img src="/tarou-docs/assets/img/artifact-img1.png" alt="alt text" width="308" height="360"></p><p>进入神器列表时获取神器信息，便于筛选。清理模式激活时，只会显示无用的神器。</p><p>下文的清理模式、配置规则、复制导入规则和技能筛选工具栏适用于桌面与扩展。移动端展示神器列表与推荐技能，支持点击推荐技能筛选、再次点击取消，以及清除推荐，不提供上述工具栏。</p><h2 id="配置规则" tabindex="-1">配置规则 <a class="header-anchor" href="#配置规则" aria-label="Permalink to “配置规则”">​</a></h2><p><img src="/tarou-docs/assets/img/artifact-img2.png" alt="alt text" width="639" height="451"></p><p>点击操作中的配置规则打开配置窗口，可以设置各种技能是否有用。</p><h2 id="复制导入规则" tabindex="-1">复制导入规则 <a class="header-anchor" href="#复制导入规则" aria-label="Permalink to “复制导入规则”">​</a></h2><p>复制规则可以复制当前的规则分享给别人，导入规则则是使用其他人分享的规则覆盖当前规则。</p><p><a href="https://bbs.nga.cn/read.php?tid=43964410" target="_blank" rel="noreferrer">NGA神器规则分享楼</a></p><h2 id="技能筛选" tabindex="-1">技能筛选 <a class="header-anchor" href="#技能筛选" aria-label="Permalink to “技能筛选”">​</a></h2><p><img src="/tarou-docs/assets/img/artifact-img3.png" alt="alt text" width="329" height="596"></p><p>点击筛选按钮打开技能筛选窗口，选中或取消技能进行神器筛选。</p><p>严格模式表示神器必须包含所有选择的技能，非严格模式表示神器只需要包含任意一个选择的技能即可。</p>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};